from hypothesis import strategies as st


@st.composite
def gen(draw):
    N = draw(st.integers(2, 5))
    all_pairs = [(a, b) for a in range(1, N + 1) for b in range(a + 1, N + 1)]
    M = draw(st.integers(0, len(all_pairs)))
    chosen = draw(st.lists(st.sampled_from(all_pairs), min_size=M, max_size=M,
                           unique=True)) if M > 0 else []
    edges = [(a, b, draw(st.integers(1, 5))) for (a, b) in chosen]
    M = len(edges)
    Q = draw(st.integers(1, 8))
    closed = set()
    lines = [f"{N} {M} {Q}"]
    for a, b, c in edges:
        lines.append(f"{a} {b} {c}")
    for _ in range(Q):
        open_roads = [i for i in range(1, M + 1) if i not in closed]
        can_close = len(open_roads) > 0
        if can_close and draw(st.booleans()):
            i = draw(st.sampled_from(open_roads))
            closed.add(i)
            lines.append(f"1 {i}")
        else:
            x = draw(st.integers(1, N - 1))
            y = draw(st.integers(x + 1, N))
            lines.append(f"2 {x} {y}")
    return "\n".join(lines) + "\n"


